"""Student passwords: generated by staff, stored only as salted scrypt hashes."""
import base64
import hashlib
import hmac
import secrets

N, R, P = 2 ** 14, 8, 1
ALPHABET = "abcdefghjkmnpqrstuvwxyz23456789"   # no look-alikes (l/1, o/0)


def new_password(length=10) -> str:
    """A random password that is easy to type: 'k7xq-m2pa-9t'."""
    chars = "".join(secrets.choice(ALPHABET) for _ in range(length))
    return "-".join(chars[i:i + 4] for i in range(0, length, 4))


def hash_password(password: str) -> str:
    salt = secrets.token_bytes(16)
    digest = hashlib.scrypt(password.encode(), salt=salt, n=N, r=R, p=P)
    return "scrypt$" + base64.b64encode(salt).decode() + "$" + base64.b64encode(digest).decode()


def check_password(password: str, stored: str) -> bool:
    try:
        _, salt, digest = stored.split("$")
        expected = base64.b64decode(digest)
        actual = hashlib.scrypt(password.encode(), salt=base64.b64decode(salt), n=N, r=R, p=P)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False
